export const D=Object.freeze({r:24,L:80,z:28,wheelZ:19,wheelT:5,railY:13,sliderZ:10,rodT:3,stroke:48});
export const initial=()=>({angle:55,playing:false,direction:1,inspect:false,plan:false,zoom:false});
export const wrap=a=>((a%360)+360)%360;
export function pose(state){
 const t=wrap(state.angle)*Math.PI/180,ax=D.r*Math.cos(t),ay=D.r*Math.sin(t),bx=ax+Math.sqrt(D.L*D.L-ay*ay);
 return {a:[ax,ay,D.z],b:[bx,0,D.z],x:bx,travel:D.L+D.r-bx,rodAngle:Math.atan2(-ay,bx-ax),theta:t,dead:Math.abs(Math.sin(t))<1e-8};
}
export function step(state,action,value){
 if(action==='angle')return{...state,angle:Math.max(0,Math.min(360,Number(value)||0)),playing:false};
 if(action==='play')return{...state,playing:!state.playing};
 if(action==='reverse')return{...state,direction:-state.direction};
 if(action==='inspect'||action==='plan'||action==='zoom')return{...state,[action]:!state[action]};
 if(action==='reset')return initial();
 return state;
}
export const advance=(state,seconds)=>state.playing?{...state,angle:wrap(state.angle+state.direction*36*Math.max(0,Math.min(seconds,.05)))}:state;

