import * as k from '/kit/iso-kit.mjs';
import {orderSurfaces} from '/leitor/occlusion.mjs';
import {D,pose} from './model.mjs';
const TAU=Math.PI*2,xy=(x,y,z)=>[x,y,z];
const circle=(x,y,r,n=48)=>Array.from({length:n},(_,i)=>[x+r*Math.cos(i*TAU/n),y+r*Math.sin(i*TAU/n)]);
const rect=(x,y,w,h)=>[[x,y],[x+w,y],[x+w,y+h],[x,y+h]];
const palettes={steel:['#ebe9e2','#d5d2c8','#b3b0a7','#8b8b85'],gold:['#dcc58a','#c8a55a','#a58342','#826535'],base:['#deded8','#c9cbc5','#a7aba5','#858e88'],dark:['#a4aaa7','#818b86','#626f69','#44534d'],pin:['#e8e5d9','#cbc8b9','#a29e8d','#807e73']};
const darkPalettes={steel:['#c1c3bb','#a8aea6','#858e85','#606e64'],gold:['#ddbc72','#bd984b','#97743a','#72582d'],base:['#777e73','#646e62','#4e5d50','#3c4d40'],dark:['#707c72','#56685a','#405446','#2b3d31'],pin:['#c7c7b9','#a7ad9b','#87917e','#677761']};
function mesh(){const faces=[];const add=(points,material,normal,segment=false)=>faces.push({points,material,normal,segment});
 function prism(ring,z0,z1,mat){
  // Input rings are convex. Top and bottom are flat, side walls have real depth.
  add(ring.map(p=>[...p,z0]),mat,[0,0,-1]);add(ring.map(p=>[...p,z1]),mat,[0,0,1]);
  for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length],l=Math.hypot(b[0]-a[0],b[1]-a[1]);add([[...a,z0],[...b,z0],[...b,z1],[...a,z1]],mat,[(b[1]-a[1])/l,(a[0]-b[0])/l,0]);}
 }
 function annulus(x,y,ri,ro,z0,z1,mat,n=64){
  for(let i=0;i<n;i++){const a=i*TAU/n,b=(i+1)*TAU/n,at=(r,t,z)=>[x+r*Math.cos(t),y+r*Math.sin(t),z],mid=(a+b)/2;
   add([at(ri,a,z1),at(ro,a,z1),at(ro,b,z1),at(ri,b,z1)],mat,[0,0,1]);
   add([at(ri,b,z0),at(ro,b,z0),at(ro,a,z0),at(ri,a,z0)],mat,[0,0,-1]);
   add([at(ro,a,z0),at(ro,b,z0),at(ro,b,z1),at(ro,a,z1)],mat,[Math.cos(mid),Math.sin(mid),0]);
   add([at(ri,b,z0),at(ri,a,z0),at(ri,a,z1),at(ri,b,z1)],mat,[-Math.cos(mid),-Math.sin(mid),0]);
  }
  for(const r of [ri,ro]){const c=circle(x,y,r,n);for(let i=0;i<n;i++)add([[...c[i],z1+.015],[...c[(i+1)%n],z1+.015]],mat,[0,0,1],true);}
 }
 const cyl=(x,y,r,z0,z1,mat)=>prism(circle(x,y,r),z0,z1,mat);
 const line=(a,b,mat='dark')=>add([a,b],mat,[0,0,1],true);
 const beam=(a,b,width,z0,z1,mat)=>{const dx=b[0]-a[0],dy=b[1]-a[1],l=Math.hypot(dx,dy),u=-dy*width/(2*l),v=dx*width/(2*l);prism([[a[0]+u,a[1]+v],[a[0]-u,a[1]-v],[b[0]-u,b[1]-v],[b[0]+u,b[1]+v]],z0,z1,mat)};
 const screw=(x,y,z)=>{cyl(x,y,1.65,z,z+.65,'pin');line([x-1,y,z+.68],[x+1,y,z+.68]);};
 return {faces,prism,cyl,annulus,beam,screw,line};
}
export function draw(state,theme='light'){
 const p=pose(state),m=mesh();
 m.prism(k.roundedPlan({x:-43,y:-39,w:164,d:78,r:5}),0,4,'base');
 // Machine feet and mounting bolts.
 for(const x of [-36,114])for(const y of [-32,32]){m.cyl(x,y,3.7,-2,0,'dark');m.screw(x,y,4);}
 // A complete fixed vertical bearing supports the revolving flywheel shaft.
 m.prism(rect(-10,-10,20,20),4,7,'dark');m.cyl(0,0,7.5,7,15,'steel');m.cyl(0,0,5.5,15,19,'pin');
 const a=p.theta;
 m.annulus(0,0,27,34,D.wheelZ,D.wheelZ+D.wheelT,'gold',80);
 for(let i=0;i<6;i++){const t=a+i*TAU/6;m.beam([7*Math.cos(t),7*Math.sin(t)],[29*Math.cos(t),29*Math.sin(t)],5,D.wheelZ+1,D.wheelZ+4,'gold');}
 m.cyl(0,0,9,18,25,'gold');m.cyl(0,0,4,25,26,'steel');m.line([-2*Math.cos(a),-2*Math.sin(a),26.04],[2*Math.cos(a),2*Math.sin(a),26.04]);
 // The eccentric pin is integral with a crank arm attached to the wheel hub.
 m.beam([0,0],p.a,7,23,25,'gold');m.cyl(...p.a.slice(0,2),3,24,D.z+D.rodT+1,'pin');
 // Two fixed guide rails retain the travelling cursor at every crank angle.
 for(const y of [-D.railY,D.railY]){m.prism(rect(45,y-3,73,6),4,8,'dark');m.prism(rect(45,y-1.5,73,3),8,11,'steel');for(const x of [48,115])m.screw(x,y,11);}
 m.prism(k.roundedPlan({x:p.x-10,y:-10,w:20,d:20,r:2}),9,19,'steel');
 for(const y of [-16,10])m.prism(rect(p.x-10,y,20,6),11,15,'dark');
 m.cyl(p.x,0,4,19,D.z,'gold');m.cyl(p.x,0,2.8,D.z,D.z+D.rodT+1,'pin');
 // A rigid machined link with two ring bearings and a recessed central web.
 const rod=[Math.cos(p.rodAngle),Math.sin(p.rodAngle)],left=[p.a[0]+rod[0]*6,p.a[1]+rod[1]*6],right=[p.b[0]-rod[0]*6,p.b[1]-rod[1]*6];
 m.beam(left,right,6,D.z,D.z+D.rodT,'steel');m.beam([left[0]+rod[0]*4,left[1]+rod[1]*4],[right[0]-rod[0]*4,right[1]-rod[1]*4],2,D.z+D.rodT,D.z+D.rodT+.25,'dark');
 for(const q of [p.a,p.b]){m.annulus(q[0],q[1],3.1,6.5,D.z,D.z+D.rodT,'steel',40);m.annulus(q[0],q[1],2.9,4,D.z+D.rodT,D.z+D.rodT+.5,'gold',32);m.cyl(q[0],q[1],2.1,D.z+D.rodT+.5,D.z+D.rodT+1.2,'pin');m.line([q[0]-.9,q[1],D.z+D.rodT+1.23],[q[0]+.9,q[1],D.z+D.rodT+1.23]);}
 // Engraved stroke scale on the base is independent of moving-part readouts.
 for(let i=0;i<=48;i+=2){const x=56+i;m.line([x,-29,4.03],[x,i%8===0?-25:-27,4.03],'dark');}
 const P=k.fitProjection([...k.boxCorners({x:-43,y:-39,w:164,d:78},-2,4),...circle(0,0,34).flatMap(p=>[[...p,19],[...p,26]]),...k.boxCorners({x:45,y:-16,w:73,d:32},4,33)],900,480,{pad:state.zoom?5:38,azimuth:state.plan?90:48,elevation:state.plan?89.9:37});
 const ar=P.azimuth*Math.PI/180,er=P.elevation*Math.PI/180,view=[Math.cos(ar)*Math.cos(er),Math.sin(ar)*Math.cos(er),Math.sin(er)];
 const planes=[4,8,11,19,23,25,28,31].map(z=>({normal:[0,0,1],offset:z}));
 const palette=theme==='dark'?darkPalettes:palettes;
 const pieces=orderSurfaces(m.faces.filter(f=>f.segment||f.normal.reduce((v,n,i)=>v+n*view[i],0)>1e-7),{planes,view}).map(f=>{
  const path=k.pathOf(f.points.map(q=>k.iso(q,P)),!f.segment),c=palette[f.material];
  if(f.segment)return `<path d="${path}" fill="none" stroke="${c[3]}" stroke-width=".65" stroke-linecap="round"/>`;
  const score=f.normal[0]*-.35+f.normal[1]*-.45+f.normal[2]*.8,band=score>.6?0:score>.1?1:score>-.3?2:3,fill=c[band];
  return `<path d="${path}" fill="${fill}" stroke="${fill}" stroke-width=".45" stroke-linejoin="round"/>`;
 }).join('');
 let overlay='';
 if(state.inspect){const q=[k.iso([0,0,D.z+4],P),k.iso([p.a[0],p.a[1],D.z+4],P),k.iso([p.b[0],p.b[1],D.z+4],P)];overlay=`<path d="${k.pathOf(q)}" fill="none" stroke="var(--cr-accent)" stroke-width="1.8" stroke-dasharray="5 5"/>`+q.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5" fill="var(--cr-paper)" stroke="var(--cr-accent)" stroke-width="2"/><text x="${x+9}" y="${y-8}" class="cr-mark">${['O','A','B'][i]}</text>`).join('');}
 return `<svg viewBox="${state.zoom?'90 40 720 384':'0 0 900 480'}" role="img" aria-label="Biela-manivela de bancada em ${state.plan?'vista superior':'vista isométrica'}, com juntas e cursor mecanicamente ligados">${pieces}${overlay}</svg>`;
}

