import {initial,pose,step,advance,D} from './model.mjs';
import {draw} from './geometry.mjs';
export function mount(root,env){
 let state=initial(),theme=env.theme,reduce=env.reducedMotion,visible=true,disposed=false,frame=0,last=0;
 root.classList.add('cr-study');
 root.innerHTML=`<div class="cr-eyebrow"><span>ESTUDO 02</span><span>BIELA · MANIVELA · CURSOR</span></div><div id="cr-art" class="cr-art"></div><div class="cr-readouts"><div><span>MANIVELA</span><output id="cr-angle"></output></div><div><span>PERCURSO DO CURSOR</span><output id="cr-travel"></output></div><div><span>OBLIQUIDADE DA BIELA</span><output id="cr-rod"></output></div></div><div class="cr-control"><label for="cr-range">Gire a manivela <span>0—360°</span></label><input id="cr-range" type="range" min="0" max="360" step="1" value="55"/><div class="cr-positions">${[0,90,180,270].map(a=>`<button id="cr-p${a}" data-angle="${a}">${a}°</button>`).join('')}</div></div><div class="cr-buttons"><button id="cr-play" data-action="play" aria-pressed="false">Reproduzir</button><button id="cr-reverse" data-action="reverse">Inverter sentido</button><button id="cr-reset" data-action="reset">Reiniciar</button><span class="cr-divider"></span><button id="cr-inspect" data-action="inspect" aria-pressed="false">Ver vínculos</button><button id="cr-plan" data-action="plan" aria-pressed="false">Vista superior</button><button id="cr-zoom" data-action="zoom" aria-pressed="false">Ampliar</button></div><p id="cr-status" class="cr-status" role="status"></p><div class="cr-note"><span class="cr-dot"></span><p><strong>Um giro. Dois percursos.</strong> O volante gira continuamente; a biela mantém 80 mm entre os pinos e o cursor percorre 48 mm. Nos pontos mortos, ele muda de sentido — a manivela continua girando.</p></div>`;
 const q=id=>root.querySelector('#cr-'+id),art=q('art');
 function render(){const p=pose(state);art.innerHTML=draw(state,theme);q('angle').textContent=state.angle.toFixed(0)+'°';q('travel').textContent=p.travel.toFixed(1)+' / 48 mm';q('rod').textContent=(Math.abs(p.rodAngle)<1e-8?0:p.rodAngle*180/Math.PI).toFixed(1)+'°';q('range').value=state.angle;
 for(const id of ['play','inspect','plan','zoom'])q(id).setAttribute('aria-pressed',String(state[id==='play'?'playing':id]));
 q('play').textContent=reduce?'Avançar 15°':state.playing?'Pausar':'Reproduzir';q('play').title=reduce?'Movimento reduzido: explore pelo controle de ângulo':'';
 for(const a of [0,90,180,270])q('p'+a).classList.toggle('selected',Math.abs(state.angle-a)<.5);
 q('status').textContent=(p.dead?'Ponto morto · inversão do cursor':state.playing?'Ciclo em movimento':'Ciclo pausado')+' · '+(state.direction===1?'Sentido direto':'Sentido inverso')+(state.inspect?' · Vínculos O–A–B visíveis':'')+(reduce?' · Movimento reduzido':'');}
 function cancel(){cancelAnimationFrame(frame);frame=0;last=0;}
 function schedule(){if(!frame&&!disposed&&visible&&!reduce&&state.playing)frame=requestAnimationFrame(tick);}
 function tick(t){frame=0;if(disposed||!visible||reduce||!state.playing){last=0;return;}const dt=last?(t-last)/1000:0;last=t;state=advance(state,dt);render();schedule();}
 const click=e=>{const button=e.target.closest('button');if(!button||!root.contains(button))return;if(button.dataset.angle!==undefined)state=step(state,'angle',button.dataset.angle);else if(button.dataset.action==='play'&&reduce)state=step(state,'angle',(state.angle+15)%360);else if(button.dataset.action)state=step(state,button.dataset.action);cancel();render();schedule();};
 const input=e=>{state=step(state,'angle',e.target.value);cancel();render();};
 const environment=e=>{theme=e.detail.theme;reduce=e.detail.reducedMotion;visible=e.detail.visible;if(reduce)state={...state,playing:false};cancel();render();schedule();};
 root.addEventListener('click',click);q('range').addEventListener('input',input);root.addEventListener('figure:environment',environment);render();
 return()=>{disposed=true;cancel();root.removeEventListener('click',click);q('range').removeEventListener('input',input);root.removeEventListener('figure:environment',environment);root.replaceChildren();};
}
